import{_ as a,o as i,c as t,a2 as n}from"./chunks/framework.CDpkVv68.js";const m=JSON.parse('{"title":"Blacksmithing","description":"","frontmatter":{},"headers":[],"relativePath":"guide/professions/blacksmithing.md","filePath":"guide/professions/blacksmithing.md"}'),r={name:"guide/professions/blacksmithing.md"};function s(o,e,l,d,h,c){return i(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="blacksmithing" tabindex="-1">Blacksmithing <a class="header-anchor" href="#blacksmithing" aria-label="Permalink to &quot;Blacksmithing&quot;">​</a></h1><p><strong>Design status: Proposed.</strong> This page describes the intended redesign, not confirmed live mechanics. <strong>Implementation/availability:</strong> not established for this redesign. <strong>Verification:</strong> documentation review only. <strong>Reviewed:</strong> 2026-10-08 against the <a href="/Syrolands-Public/game-design/professions/blacksmithing.html">full design specification</a>.</p><h2 id="what-it-does" tabindex="-1">What it does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to &quot;What it does&quot;">​</a></h2><p>Blacksmithing turns ore and metal into useful equipment through smelting, refining, alloying, forging, heat treatment and finishing. Materials and process should create tradeoffs: a harder edge can be brittle, while toughness, weight and durability pull in different directions.</p><h2 id="why-take-it-into-the-field" tabindex="-1">Why take it into the field? <a class="header-anchor" href="#why-take-it-into-the-field" aria-label="Permalink to &quot;Why take it into the field?&quot;">​</a></h2><p>Assessment, sharpening, minor repairs and field maintenance should make metalworking knowledge useful on an expedition. Arms Lore explains martial performance; Blacksmithing explains material and structural qualities. Together they could reveal more about equipment.</p><h2 id="learning-and-specialization" tabindex="-1">Learning and specialization <a class="header-anchor" href="#learning-and-specialization" aria-label="Permalink to &quot;Learning and specialization&quot;">​</a></h2><p>The Metallurgical Journal tracks understanding of materials and processes. Bladesmithing and Armorsmithing are learned technique examples. A smith might become known for durable field weapons or lightweight armor through actual workmanship rather than a single reputation score.</p><h2 id="progression-and-related-crafts" tabindex="-1">Progression and related crafts <a class="header-anchor" href="#progression-and-related-crafts" aria-label="Permalink to &quot;Progression and related crafts&quot;">​</a></h2><p><a href="/Syrolands-Public/guide/professions/overview.html">Shared learning and batching</a> apply. Better skill broadens capable work; <a href="/Syrolands-Public/guide/items/item-quality.html">quality</a> depends on materials, techniques and execution, with rare Masterworks never routine at 100. <a href="/Syrolands-Public/guide/professions/mining.html">Mining</a> supplies geological knowledge and <a href="/Syrolands-Public/guide/professions/carpentry.html">Carpentry</a> helps with composite items. Exact repair and material rules remain open.</p><p><a href="/Syrolands-Public/guide/professions/overview.html">All professions</a> · <a href="/Syrolands-Public/game-design/professions/blacksmithing.html">Full design specification</a></p>',11)])])}const p=a(r,[["render",s]]);export{m as __pageData,p as default};
